{"l":9015,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'praktisk og jordnær' på engelsk?","o":["dogmatic","pragmatic","dramatic","erratic"],"a":"pragmatic","r":"'Pragmatic' betyder praktisk orienteret."},
