{"l":9043,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'modvilje' på engelsk?","o":["reluctance","relevance","reliance","resonance"],"a":"reluctance","r":"'Reluctance' er navneordet til 'reluctant': modvilje."},
{"l":9050,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder 'disgruntled' i 'The disgruntled fans left the stadium before the final whistle.'?","o":["begejstrede","utilfredse","forvirrede","udmattede"],"a":"utilfredse","r":"'Disgruntled' betyder utilfreds eller sur; fansene gik før tid, fordi de var utilfredse."},
