{"l":9194,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'evig / vedvarende' på engelsk?","o":["punctual","perceptual","spiritual","perpetual"],"a":"perpetual","r":"'Perpetual' = evig."},
